//! Recorded robots instructions, with source and exact agent scope.
use serde::{Serialize,Deserialize};
#[derive(Debug,Clone,Serialize,Deserialize)]pub struct Rule{pub source:String,pub agent:String,pub value:String,pub flags:Vec<String>}
fn flags(value:&str)->Vec<String>{let mut result=Vec::new();for part in value.split(','){if part.contains(':'){continue}for word in part.split_whitespace(){let word=word.to_ascii_lowercase();if matches!(word.as_str(),"noindex"|"nofollow"|"index"|"follow"|"none"|"all")&&!result.contains(&word){result.push(word)}}}result}
pub fn meta(name:&str,value:&str)->Option<Rule>{let agent=name.to_ascii_lowercase();if !matches!(agent.as_str(),"robots"|"googlebot"|"googlebot-news"|"bingbot"){return None}Some(Rule{source:"HTML meta".into(),agent:if agent=="robots"{"*".into()}else{agent},value:value.into(),flags:flags(value)})}
fn agent_token(value:&str)->bool{!value.is_empty()&&value.len()<=128&&value.bytes().all(|b|b.is_ascii_alphanumeric()||matches!(b,b'-'|b'_'|b'*'|b'.'))&&value.as_bytes()[0].is_ascii_alphabetic()}
pub fn headers(value:&str)->Vec<Rule>{let mut result=Vec::new();for (line,value)in value.lines().enumerate(){let mut agent="*".to_string();for part in value.split(','){let mut value=part.trim();if let Some((prefix,rest))=value.split_once(':'){let prefix=prefix.trim().to_ascii_lowercase();if agent_token(&prefix)&&!matches!(prefix.as_str(),"max-snippet"|"max-image-preview"|"max-video-preview"|"unavailable_after"){agent=prefix;value=rest.trim();}}if !value.is_empty(){result.push(Rule{source:format!("X-Robots-Tag line {}",line+1),agent:agent.clone(),value:value.into(),flags:flags(value)})}}}result}
pub fn restriction(page:&crate::Page,agent:&str,flag:&str)->bool{if let Some(rules)=&page.directive_rules{return rules.iter().filter(|r|r.agent=="*"||r.agent.eq_ignore_ascii_case(agent)).any(|r|r.flags.iter().any(|word|word==flag||word=="none"))}page.directives.split(|c:char|c==','||c==':'||c.is_whitespace()).any(|word|word.eq_ignore_ascii_case(flag)||word.eq_ignore_ascii_case("none"))}
#[cfg(test)]mod tests{use super::*;
 #[test]fn scoped_headers_parameters_and_restrictive_union(){let mut page=crate::Page::default();page.directive_rules=Some(vec![meta("ROBOTS","index, follow").unwrap(),meta("googlebot","NOINDEX").unwrap()]);page.directive_rules.as_mut().unwrap().extend(headers("bingbot: nofollow, max-snippet: 0\nnoimageindex\nGooglebot: nofollow"));assert!(restriction(&page,"googlebot","noindex"));assert!(restriction(&page,"googlebot","nofollow"));assert!(!restriction(&page,"bingbot","noindex"));assert!(restriction(&page,"bingbot","nofollow"));assert!(!restriction(&page,"*","noindex"));assert!(meta("description","noindex").is_none())}
 #[test]fn exact_tokens_none_and_parameter_values(){let mut page=crate::Page::default();page.directive_rules=Some(headers("max-snippet: noindex, unavailable_after: Wed, 25 Jun 2030 15:00:00 GMT, noindexable"));assert!(!restriction(&page,"googlebot","noindex"));page.directive_rules=Some(vec![meta("robots","none, follow").unwrap()]);assert!(restriction(&page,"googlebot","noindex"));assert!(restriction(&page,"googlebot","nofollow"));page.directive_rules=None;page.directives="NONE".into();assert!(restriction(&page,"googlebot","noindex"))}
}
